def lower_bound(arr, target):
    # lo < hi form: search a HALF-OPEN space, converges on one index, no return -1
    lo, hi = 0, len(arr)          # hi = len(arr): the 'not found' slot is valid
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < target:     # KNOB: predicate; True -> answer is strictly right
            lo = mid + 1
        else:
            hi = mid              # mid may still be the answer, so keep it
    return lo                     # first index with arr[i] >= target

def exact_find(arr, target):
    # lo <= hi form: use ONLY when you want the exact value or -1
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def binary_search_answer(lo, hi, feasible):
    while lo < hi:                # smallest value that is feasible
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def stack_scan(tokens):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for t in tokens:
        if t in pairs:                      # KNOB: what counts as a 'closer'
            if not stack or stack[-1] != pairs[t]:
                return False                # unmatched closer
            stack.pop()                     # resolve with the most recent opener
        else:
            stack.append(t)                 # KNOB: what you push (token, index, or state tuple)
    return not stack                        # leftovers mean unclosed openers

