@lru_cache(maxsize=None)
def rec_memo(i, j):                     # memoize when subproblems repeat
    if i >= j:
        return 0
    return 1 + min(rec_memo(i + 1, j), rec_memo(i, j - 1))

def dfs_graph(graph, start):
    visited = set()

    def dfs(u):
        visited.add(u)            # mark on ENTRY to avoid revisits/cycles
        for v in graph[u]:        # KNOB: neighbor generation (adj list, grid deltas)
            if v not in visited:
                dfs(v)
    dfs(start)
    return visited

def dfs_grid_iter(grid, sr, sc):
    R, C = len(grid), len(grid[0])
    stack = [(sr, sc)]
    seen = {(sr, sc)}
    count = 0
    while stack:
        r, c = stack.pop()
        count += 1
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in seen \
               and grid[nr][nc] == 1:      # KNOB: the passable test
                seen.add((nr, nc))
                stack.append((nr, nc))
    return count

def search(root, target):
    node = root
    while node:
        if node.val == target:
            return node
        node = node.left if target < node.val else node.right   # discard half
    return None

def validate(root):
    def ok(node, low, high):        # KNOB: pass the allowed RANGE down, not just the parent
        if not node:
            return True
        if not (low < node.val < high):
            return False
        return ok(node.left, low, node.val) and ok(node.right, node.val, high)
    return ok(root, float('-inf'), float('inf'))

def kth_smallest(root, k):
    stack, cur = [], root
    while cur or stack:             # in-order yields sorted values
        while cur:
            stack.append(cur)
            cur = cur.left
        cur = stack.pop()
        k -= 1
        if k == 0:
            return cur.val
        cur = cur.right

class TrieNode:
    __slots__ = ("children", "is_word")
    def __init__(self):
        self.children = {}        # KNOB: dict vs [None]*26 array
        self.is_word = False      # KNOB: bool vs count vs stored payload

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_word = True

    def _walk(self, s):
        node = self.root
        for ch in s:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.is_word

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

import heapq

def top_k(nums, k):
    heap = []                          # MIN-heap of size k -> keeps the k LARGEST
    for x in nums:
        heapq.heappush(heap, x)        # KNOB: push a tuple (key, tiebreak, payload)
        if len(heap) > k:
            heapq.heappop(heap)        # evict the smallest survivor
    return heap                        # heap[0] is the k-th largest

def dijkstra(graph, src):
    dist = {src: 0}
    pq = [(0, src)]                    # (cost, node); Python heaps are MIN-heaps
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float('inf')):
            continue                   # stale entry: lazy deletion
        for v, w in graph[u]:
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

from functools import lru_cache

def dp_topdown(nums, target):
    @lru_cache(maxsize=None)         # state args must be hashable/immutable
    def f(i, rem):                   # KNOB: the STATE definition
        if rem == 0:
            return 1                 # KNOB: base cases
        if i == len(nums) or rem < 0:
            return 0
        take = f(i + 1, rem - nums[i])
        skip = f(i + 1, rem)
        return take + skip           # KNOB: the transition/combine
    return f(0, target)

def dp_bottomup(nums, target):
    dp = [0] * (target + 1)
    dp[0] = 1                        # base case
    for x in nums:                   # item-outer = combinations (0/1 or unbounded)
        for r in range(target, x - 1, -1):   # reverse => each item used ONCE
            dp[r] += dp[r - x]
    return dp[target]

from math import gcd, isqrt

MOD = 10 ** 9 + 7

def lcm(a, b):
    return a // gcd(a, b) * b           # divide BEFORE multiplying to limit growth

def is_prime(n):
    if n < 2:
        return False
    for p in range(2, isqrt(n) + 1):    # KNOB: trial division only to sqrt(n)
        if n % p == 0:
            return False
    return True

def sieve(n):
    prime = [True] * (n + 1)
    prime[0:2] = [False, False]
    for p in range(2, isqrt(n) + 1):
        if prime[p]:
            for m in range(p * p, n + 1, p):   # start at p*p, not 2*p
                prime[m] = False
    return [i for i, ok in enumerate(prime) if ok]

def power_mod(base, exp, mod=MOD):
    return pow(base, exp, mod)          # fast modular exponentiation, O(log exp)

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n                  # number of disjoint sets

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]   # path compression
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False                # already together -> this edge closes a cycle
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra             # attach the smaller tree under the larger
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.count -= 1
        return True

from functools import cmp_to_key

def sort_variants(items):
    items.sort()                                    # in place, stable
    by_key = sorted(items, key=lambda x: (x[1], -x[0]))   # KNOB: multi-key, - reverses numerics
    def cmp(a, b):                                  # KNOB: comparator when the rule is pairwise
        if a + b > b + a:
            return -1                               # a comes first
        if a + b < b + a:
            return 1
        return 0
    by_cmp = sorted(map(str, items), key=cmp_to_key(cmp))
    return by_key, by_cmp

def counting_sort(nums, k):
    cnt = [0] * (k + 1)                             # values in 0..k
    for x in nums:
        cnt[x] += 1
    out = []
    for v, c in enumerate(cnt):
        out.extend([v] * c)                         # O(n + k), beats n log n for small k
    return out

class DesignSkeleton:
    def __init__(self, capacity):
        self.cap = capacity
        self.index = {}          # KNOB: key -> node/position, gives O(1) lookup
        self.order = []          # KNOB: the ordering/eviction structure (list, dll, heap)

    def get(self, key):
        if key not in self.index:
            return -1
        self._touch(key)         # keep the invariant on every access, not just writes
        return self.index[key]

    def put(self, key, value):
        if key in self.index:
            self.index[key] = value
            self._touch(key)
            return
        if len(self.index) >= self.cap:
            victim = self._evict()          # KNOB: the eviction policy
            del self.index[victim]
        self.index[key] = value
        self.order.append(key)

    def _touch(self, key):
        self.order.remove(key)              # O(n) here; a doubly linked list makes it O(1)
        self.order.append(key)

    def _evict(self):
        return self.order.pop(0)

