def normalize(s):
    return ''.join(ch.lower() for ch in s if ch.isalnum())   # KNOB: the canonical form

def is_anagram(a, b):
    return Counter(a) == Counter(b)          # KNOB: Counter vs sorted() vs a 26-int array

def build_output(parts):
    out = []                                  # NEVER s += ch in a loop: O(n^2)
    for p in parts:
        out.append(str(p))
    return ''.join(out)

def expand_around_center(s):
    best = ""
    for i in range(len(s)):
        for l, r in ((i, i), (i, i + 1)):     # odd and even length centers
            while l >= 0 and r < len(s) and s[l] == s[r]:
                l -= 1
                r += 1
            cand = s[l + 1:r]                 # l,r are one past the valid range
            if len(cand) > len(best):
                best = cand
    return best

def divide_conquer(arr, lo, hi):
    if lo >= hi:                       # KNOB: base case (0 or 1 element)
        return base(arr, lo, hi)
    mid = (lo + hi) // 2
    left = divide_conquer(arr, lo, mid)
    right = divide_conquer(arr, mid + 1, hi)
    return merge(left, right)          # KNOB: the cross-boundary combine

def merge_sort(a):
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    L, R = merge_sort(a[:mid]), merge_sort(a[mid:])
    out, i, j = [], 0, 0
    while i < len(L) and j < len(R):
        if L[i] <= R[j]:               # <= keeps the sort STABLE
            out.append(L[i]); i += 1
        else:
            out.append(R[j]); j += 1   # cross-pair counting hooks in here
    out.extend(L[i:]); out.extend(R[j:])
    return out

def simulate(instructions, steps):
    DIRS = [(0, 1), (1, 0), (0, -1), (-1, 0)]   # KNOB: direction order = turn semantics
    r = c = d = 0                                # state: position + facing
    seen = {}                                    # KNOB: state -> step, for cycle shortcuts
    for step in range(steps):
        key = (r, c, d)
        if key in seen:                          # a cycle: skip ahead instead of looping
            period = step - seen[key]
            remaining = (steps - step) % period
            return advance(r, c, d, remaining)
        seen[key] = step
        op = instructions[step % len(instructions)]
        if op == 'R':
            d = (d + 1) % 4                      # right turn
        elif op == 'L':
            d = (d - 1) % 4
        else:
            dr, dc = DIRS[d]
            r, c = r + dr, c + dc                # KNOB: apply bounds/collision rules here
    return r, c, d

def cyclic_sort(nums):
    i = 0
    n = len(nums)
    while i < n:
        j = nums[i] - 1                  # KNOB: -1 for 1..n, no offset for 0..n-1
        if 0 <= j < n and nums[i] != nums[j]:
            nums[i], nums[j] = nums[j], nums[i]   # swap into place; do NOT advance i
        else:
            i += 1                       # in place or out of range -> move on
    return nums

def find_missing_and_duplicate(nums):
    cyclic_sort(nums)
    missing, duplicate = [], []
    for i, x in enumerate(nums):
        if x != i + 1:                   # KNOB: the post-scan mismatch test
            missing.append(i + 1)
            duplicate.append(x)
    return missing, duplicate
